actions.script:
def zinr = context.zinr
def fromD = (fromDate ?: ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd'))
def thruD = (thruDate ?: fromD)
def ds = java.sql.Timestamp.valueOf(fromD + ' 00:00:00')
def de = java.sql.Timestamp.valueOf(thruD + ' 23:59:59')
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
periodStr = fromD + ' to ' + thruD
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
def tf = ec.entity.find("zenith.erp.pos.PosTransaction").condition("statusId","PtCompleted")
    .condition("entryDate","greater-equals",ds).condition("entryDate","less-equals",de)
if (_org && _org != '_NA_') tf.condition("organizationPartyId", _org)
def txnIds = tf.list().collect { it.transactionId }
def pm = new LinkedHashMap()
if (txnIds) {
    ec.entity.find("zenith.erp.pos.PosTransactionItem").condition("transactionId","in",txnIds).list().each { it2 ->
        def key = it2.productId ?: it2.productName ?: 'Unknown'
        if (!pm[key]) pm[key] = [pid:(it2.productId ?: ''), pname:(it2.productName ?: it2.productId ?: 'Unknown'), qty:0.0G, amt:0.0G, bills:0]
        pm[key].qty += (it2.quantity ?: 0) as BigDecimal
        pm[key].amt += (it2.lineTotal ?: 0) as BigDecimal
        pm[key].bills++
    }
}
def all = pm.values().sort { -(it.amt as BigDecimal) }
def stx = (searchText ?: '').trim().toLowerCase()
if (stx) all = all.findAll { ((it.pname ?: '').toLowerCase().contains(stx) || (it.pid ?: '').toLowerCase().contains(stx)) }
def num = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00')) }
def intn = { v -> zinr.inr(ec.l10n.format((v ?: 0) as BigDecimal, '#,##0')) }
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
rows = all.collect { r ->
    def avg = r.qty > 0 ? (r.amt / r.qty) : 0.0G
    [pname:x(r.pname), pid:x(r.pid), qty:intn(r.qty), avg:num(avg), amt:num(r.amt), bills:r.bills.toString()] }
rowCountStr = all.size().toString()
totalAmtStr = num(all.inject(0.0G) { a, it -> a + (it.amt as BigDecimal) })
